BEGIN

-- call `mm-commissions-reporting.COMISIONES.camp_gescales_netllar`()

  --Eliminamos si exite información de la liquidación para no duplicar.
  DELETE `mm-commissions-reporting.TEMP.camp_gescales_netllar` 
  WHERE mes = DATE_TRUNC(CURRENT_DATE(), MONTH)

;

  --Insertamos la información en la tabla para que se calcule la campaña por el procedimiento general
  INSERT INTO `mm-commissions-reporting.TEMP.camp_gescales_netllar` (
  SELECT  
    DATE_TRUNC(CURRENT_DATE(), MONTH) AS mes,
    LEFT(a.GESCAL,17) AS Gescal, 
    current_sfid_id AS codigo_operador, 
    sector,
    nombre_comercio,
    documento AS cif,
    a.phone_nm,
    tariff_id,
    tariff_ds,
    CASE WHEN order_day_id IS NOT NULL AND activation_date IS NULL THEN 'En vuelo'
          WHEN order_day_id IS NOT NULL AND activation_date IS NOT NULL AND deactivation_date <= CURRENT_DATE() THEN 'Baja'
          WHEN order_day_id IS NOT NULL AND activation_date IS NOT NULL AND deactivation_date > CURRENT_DATE() THEN 'Activo'
          ELSE NULL END AS Estado,
    order_day_id, 
    activation_date, 
    deactivation_date, 
  FROM `mm-datamart-kd.SERVICES.ventas_base_net` a
  LEFT JOIN (
  SELECT id_comisionista,nombre_comercio,documento
  FROM `mm-commissions-reporting.GS.DEALERS_MARBLANCA`
  ) b ON a.current_sfid_id = b.id_comisionista
  INNER JOIN (
    SELECT gescal,
      nombre AS sector,
      phone_nm
    FROM `mm-commissions-reporting.GS.GESCALES_NETLLAR_MAESTRO`
  ) c ON a.phone_nm = CAST(c.phone_nm AS INT64) AND LEFT(a.GESCAL,17) = c.gescal 
  WHERE comm_brand_ds = 'MARBLANCA' 
        AND order_day_id >= '2024-11-01'
        AND current_sfid_id = 'C09-00062'
        AND LEFT(a.GESCAL,17) IN
